package com.example.minicommerce.payment.api;
import com.example.minicommerce.payment.application.*;import com.example.minicommerce.payment.application.PaymentTransactionService.PaymentView;import com.example.minicommerce.refund.application.RefundService;import com.example.minicommerce.refund.application.RefundService.RefundView;import com.example.minicommerce.shared.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payments")public class PaymentController{private final PaymentOrchestrator payments;private final PaymentWebhookService webhooks;private final RefundService refunds;private final CurrentUser current;public PaymentController(PaymentOrchestrator p,PaymentWebhookService w,RefundService r,CurrentUser c){payments=p;webhooks=w;refunds=r;current=c;}@PostMapping("/orders/{orderId}")public PaymentView pay(@PathVariable UUID orderId,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody PayRequest request){return payments.pay(orderId,current.require(),key,request.paymentToken());}@PostMapping("/{paymentId}/refunds")public RefundView refund(@PathVariable UUID paymentId,@RequestHeader("Idempotency-Key")String key){return refunds.refund(paymentId,current.require(),key);}@PostMapping("/webhooks/fake")public void webhook(@RequestHeader(value="X-Payment-Signature",required=false)String signature,@RequestBody String body)throws Exception{webhooks.handle(body,signature);}public record PayRequest(@NotBlank String paymentToken){}}
